// Lightweight, code-native illustrations: no missing photos or image downloads.
function carArt(color='#ff762c',variant='suv',suffix='art'){const high=variant==='suv',roof=high?'M146 146L191 84Q202 72 226 72H353Q378 74 402 108L431 146Z':'M142 146L209 99Q225 88 248 88H351Q369 90 396 116L430 147Z';return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 620 280" role="img" aria-label="Стилизованная иллюстрация автомобиля"><defs><linearGradient id="paint-${suffix}" x2=".3" y2="1"><stop stop-color="${color}"/><stop offset="1" stop-color="${color}" stop-opacity=".76"/></linearGradient><linearGradient id="glass-${suffix}" x2="1" y2="1"><stop stop-color="#b4edff"/><stop offset="1" stop-color="#1d5687"/></linearGradient></defs><ellipse cx="310" cy="244" rx="254" ry="16" fill="#102b58" opacity=".15"/><path d="${roof}" fill="url(#paint-${suffix})" stroke="#142b55" stroke-width="3"/><path d="M178 141L214 ${high?'88':'106'}H275V140Z" fill="url(#glass-${suffix})"/><path d="M287 ${high?'87':'104'}H347Q364 87 393 139H287Z" fill="url(#glass-${suffix})"/><path d="M66 164Q94 147 150 143H432L537 160Q563 166 570 185L568 214Q553 227 524 227H98Q63 225 55 207V184Q57 170 66 164Z" fill="url(#paint-${suffix})" stroke="#142b55" stroke-width="3"/><path d="M73 174Q289 157 534 178" fill="none" stroke="white" opacity=".6" stroke-width="3"/><path d="M78 218H547" stroke="#152c49" stroke-width="12"/><path d="M273 149V214M414 153V214" stroke="#142b55" opacity=".35" stroke-width="2"/><rect x="300" y="157" width="25" height="5" rx="2" fill="#142b55" opacity=".6"/><rect x="445" y="160" width="23" height="5" rx="2" fill="#142b55" opacity=".6"/><path d="M66 178H113L106 190H62Z" fill="#d6faff"/><path d="M530 176L560 184L563 194H533Z" fill="#ff3d5e"/><path d="M67 203H104" stroke="#102344" stroke-width="6"/><path d="M190 228a46 46 0 0 0-92 0M521 228a46 46 0 0 0-92 0" fill="#142b55"/><g fill="#14243b" stroke="#0b172b" stroke-width="3"><circle cx="144" cy="220" r="35"/><circle cx="475" cy="220" r="35"/></g><g fill="#e2e9ed" stroke="#8298aa" stroke-width="5"><circle cx="144" cy="220" r="22"/><circle cx="475" cy="220" r="22"/></g><g fill="#364f69"><circle cx="144" cy="220" r="8"/><circle cx="475" cy="220" r="8"/></g><path d="M163 133H190V149H164Q155 143 163 133Z" fill="${color}" stroke="#142b55" stroke-width="2"/></svg>`;}
const mountainScene=`<svg class="mountain-art" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1000 750" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="sky" x2="0" y2="1"><stop stop-color="#123b87"/><stop offset="1" stop-color="#60b8ea"/></linearGradient><linearGradient id="snowblue" x2="1" y2="1"><stop stop-color="#ecfcff"/><stop offset="1" stop-color="#66a4e1"/></linearGradient></defs><path fill="url(#sky)" d="M0 0H1000V750H0Z"/><circle cx="790" cy="165" r="77" fill="#ffe8a3"/><circle cx="790" cy="165" r="105" fill="#ffe8a3" opacity=".08"/><path d="M0 458L178 223L273 337L445 89L508 176L565 119L820 424L1000 268V750H0Z" fill="#3173bc"/><path d="M178 223L132 323L179 296L199 313L213 266ZM445 89L344 236L416 205L446 237L475 202L506 247L565 119L516 163L508 176Z" fill="#e9faff"/><path d="M0 580L176 397L280 469L491 224L682 423L804 292L1000 474V750H0Z" fill="url(#snowblue)"/><path d="M491 224L427 413L481 372L505 414L537 365L588 393Z" fill="#f4ffff"/><path d="M0 750V625L271 505L477 552L754 458L1000 559V750Z" fill="#428dc5"/><path d="M0 750V680L226 601L486 665L748 544L1000 650V750Z" fill="#bde6f5"/><path d="M1000 750H215Q286 669 510 648T915 559L1000 555Q960 630 645 688T481 750Z" fill="#19385c"/><path d="M1000 568Q925 630 608 689T414 750" fill="none" stroke="#e0f5ff" stroke-width="4" stroke-dasharray="24 24"/><g fill="#1d6393"><path d="M772 516l-25 62h50Z"/><path d="M821 516l-34 82h68Z"/><path d="M869 527l-23 61h46Z"/><path d="M79 599l-24 65h48Z"/></g></svg>`;
const hero=document.querySelector('.hero');hero.querySelector('h1').innerHTML='Горы зовут.<br><em>Жми на драйв!</em>';hero.querySelector('p').innerHTML='Собирай друзей, выбирай машину.<br>Ваше приключение начинается в Минеральных Водах.';hero.querySelector('.eyebrow').textContent='ФАЭТОН / МИНЕРАЛЬНЫЕ ВОДЫ / КМВ';hero.querySelector('.hero-caption').innerHTML='СНЕЖНЫЕ ВЕРШИНЫ. ЯРКИЕ ПОЕЗДКИ.<br>ТВОЯ ИСТОРИЯ НАЧИНАЕТСЯ ЗА РУЛЕМ.';hero.querySelector('.button').innerHTML='Выбрать машину <span aria-hidden="true">🚙</span>';
const art=document.createElement('div');art.className='drive-art';art.innerHTML=mountainScene+`<div class="hero-car">${carArt('#ff762c','suv','hero')}</div>`;hero.append(art);
const snow=document.createElement('div');snow.className='snow';snow.setAttribute('aria-hidden','true');snow.innerHTML=Array.from({length:23},(_,i)=>`<i style="left:${i*4.7}%;animation-delay:-${i*.8}s;animation-duration:${9+i%5}s"></i>`).join('');hero.append(snow);
const seasons=document.createElement('div');seasons.className='season-controls';seasons.setAttribute('aria-label','Оформление пейзажа');seasons.innerHTML='<button data-season="winter" aria-pressed="true">❄ Снежный драйв</button><button data-season="autumn" aria-pressed="false">🍁 Золотая осень</button>';hero.querySelector('.hero-copy').append(seasons);
seasons.querySelectorAll('button').forEach(b=>b.onclick=()=>{const autumn=b.dataset.season==='autumn';document.body.classList.toggle('autumn',autumn);seasons.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));art.querySelector('#sky stop:first-child').setAttribute('stop-color',autumn?'#593752':'#123b87');art.querySelector('#sky stop:last-child').setAttribute('stop-color',autumn?'#ffb366':'#60b8ea');art.querySelector('#snowblue stop:first-child').setAttribute('stop-color',autumn?'#e7bc6a':'#ecfcff');art.querySelector('#snowblue stop:last-child').setAttribute('stop-color',autumn?'#ba643d':'#66a4e1');hero.querySelector('.hero-caption').innerHTML=autumn?'ЗОЛОТАЯ ОСЕНЬ. ЯРКИЕ ПОЕЗДКИ.<br>ТВОЯ ИСТОРИЯ НАЧИНАЕТСЯ ЗА РУЛЕМ.':'СНЕЖНЫЕ ВЕРШИНЫ. ЯРКИЕ ПОЕЗДКИ.<br>ТВОЯ ИСТОРИЯ НАЧИНАЕТСЯ ЗА РУЛЕМ.';});
document.querySelector('#fleet h2').innerHTML='Выбирай характер.<br>Забирай ключи.';document.querySelector('#fleet .section-top>p').innerHTML='Для маленьких побегов из города<br>и больших историй с друзьями.';document.querySelector('#how h2').innerHTML='Без квестов.<br>Сразу к поездке.';document.querySelector('#terms h2').textContent='Без сюрпризов на финише.';document.querySelector('.booking h2').textContent='На старт. Внимание…';document.querySelector('footer>p').textContent='Меньше рутины. Больше серпантинов.';
// Replace unavailable draft photos with distinct honest vector vehicle illustrations.
function decorateCars(){document.querySelectorAll('.car').forEach((card,i)=>{const id=card.querySelector('[data-car]').dataset.car;const type=id==='tucson'?'suv':'sedan',color=id==='solaris'?'#168a9c':id==='k5'?'#ff762c':'#306adf';const image=card.querySelector('.image');image.querySelector('img')?.remove();if(!image.querySelector('svg'))image.insertAdjacentHTML('afterbegin',carArt(color,type,`catalog-${id}`));card.querySelector('.pick').innerHTML='Поехали 🚙';});}decorateCars();new MutationObserver(decorateCars).observe(document.querySelector('#cars'),{childList:true});
const ribbon=document.createElement('div');ribbon.className='road-ribbon';ribbon.setAttribute('aria-hidden','true');ribbon.innerHTML=`<div class="ribbon-car">${carArt('#ff762c','suv','ribbon-one')}</div><div class="ribbon-car second">${carArt('#73e9ed','sedan','ribbon-two')}</div>`;document.querySelector('#how').after(ribbon);
const tips=document.createElement('section');tips.id='tips';tips.className='section tips';tips.innerHTML=`<div class="section-top"><div><span class="eyebrow">БАГАЖНИК ПОЛЕЗНЫХ ИДЕЙ</span><h2>Лайфхаки в дорогу.<br>Бери на заметку!</h2></div><p>Маленькая подготовка —<br>и в поездке больше места для впечатлений.</p></div><div class="tips-grid"><article class="tip"><span class="tip-icon" aria-hidden="true">📸</span><h3>Сначала кадры.<br>Потом километры.</h3><p>Сфотографируй автомобиль при получении и возврате: кузов, салон, топливо и пробег.</p><details><summary>Что снять?</summary><p>Обойди машину со всех сторон. Отдельно сними уже имеющиеся повреждения и отметь их вместе с менеджером в акте.</p></details></article><article class="tip"><span class="tip-icon" aria-hidden="true">🗺️</span><h3>Карты — в офлайн.<br>Впечатления — в память.</h3><p>Загрузи карту региона до выезда. Сохрани адрес получения машины и контакт прокатчика.</p><details><summary>Мини-чеклист</summary><p>Карта, адреса, зарядка для телефона. Проверь, что скачанная карта открывается без интернета.</p></details></article><article class="tip"><span class="tip-icon" aria-hidden="true">🎒</span><h3>Всё влезет?<br>Проверь до старта.</h3><p>Считай не только пассажиров, но и чемоданы. Для семейной поездки заранее обсуди детское кресло.</p><details><summary>Как выбрать машину?</summary><p>Сообщи менеджеру число пассажиров, объем багажа и план поездки. Вместимость и комплектацию уточняют для конкретного автомобиля.</p></details></article></div><div class="checklist" aria-label="Чеклист перед поездкой"><label><input type="checkbox"> Карта скачана</label><label><input type="checkbox"> Зарядка с собой</label><label><input type="checkbox"> Багаж посчитан</label><label><input type="checkbox"> Плейлист готов 🎵</label></div>`;ribbon.after(tips);
const nav=document.querySelector('nav');const tipsLink=document.createElement('a');tipsLink.href='#tips';tipsLink.textContent='Лайфхаки';nav.append(tipsLink);document.querySelector('.nav-cta').textContent='Поехали 🚙';document.querySelector('#find').textContent='Подобрать 🚙';document.querySelector('.demo').textContent='Демо-автопарк: цены и иллюстрации для примера. Фактические машины, наличие и условия подтверждает менеджер.';
const track=document.createElement('div');track.className='page-car-track';track.setAttribute('aria-hidden','true');track.innerHTML='<svg class="page-car" viewBox="0 0 40 72"><rect x="3" y="13" width="5" height="13" rx="2" fill="#102344"/><rect x="32" y="13" width="5" height="13" rx="2" fill="#102344"/><rect x="3" y="48" width="5" height="13" rx="2" fill="#102344"/><rect x="32" y="48" width="5" height="13" rx="2" fill="#102344"/><rect x="7" y="3" width="26" height="65" rx="10" fill="#ff762c" stroke="white" stroke-width="2"/><path d="M11 24L14 15H26L29 24ZM12 48L14 56H26L28 48Z" fill="#a5e6fc"/><rect x="12" y="28" width="16" height="17" rx="3" fill="#ffac55"/><path d="M10 6H15M25 6H30" stroke="#fff5be" stroke-width="3"/></svg>';document.body.append(track);
let ticking=false;function updateCar(){const full=document.documentElement.scrollHeight-innerHeight,fraction=full>0?Math.min(1,Math.max(0,scrollY/full)):0;track.style.setProperty('--travel',`${fraction*Math.max(0,track.clientHeight-65)}px`);ticking=false;}addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(updateCar);ticking=true;}},{passive:true});addEventListener('resize',updateCar);updateCar();
const motion=document.createElement('button');motion.className='motion-control';const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let paused=reduced;motion.setAttribute('aria-pressed',String(paused));function setMotion(){document.body.classList.toggle('no-motion',paused);motion.textContent=paused?'▶ Включить движение':'Ⅱ Остановить движение';motion.setAttribute('aria-pressed',String(paused));}motion.onclick=()=>{paused=!paused;setMotion();};document.body.append(motion);setMotion();
if('IntersectionObserver'in window){const observer=new IntersectionObserver(entries=>entries.forEach(x=>{if(x.isIntersecting){x.target.classList.add('visible');observer.unobserve(x.target);}}),{threshold:.06});document.querySelectorAll('.section-top,.journey>div,.journey li,.tip,.terms-grid article').forEach(x=>{x.classList.add('reveal');observer.observe(x);});document.body.classList.add('motion-ready');}
